        self.n = n
        self.k = k
        self.s = s
        self.pairs = {i: [] for i in range(1, k + 1)}
        self.open_to_close = {}
        self.close_to_open = {}
        self.initialize_bracket_pairs()

    def initialize_bracket_pairs(self):
        stack = []
        for i, bracket in enumerate(self.s):
            if bracket > 0:
                stack.append((i, bracket))
            else:
                if stack and stack[-1][1] == -bracket:
                    open_idx, open_bracket = stack.pop()
                    self.pairs[open_bracket].append((open_idx, i))
                    self.pairs[-bracket].append((open_idx, i))
                    self.open_to_close[open_idx] = i
                    self.close_to_open[i] = open_idx
                else:
                    stack.append((i, bracket))
        if stack:
            raise ValueError("Invalid bracket sequence")

    def replace_bracket(self, i, t):
        if self.s[i - 1] > 0:
            open_bracket = self.s[i - 1]
            self.pairs[open_bracket].remove((self.close_to_open[i - 1], i - 1))
            if not self.pairs[open_bracket]:
                del self.pairs[open_bracket]
            del self.close_to_open[i - 1]
        else:
