            del self.open_to_close[i - 1]

        self.s[i - 1] = t

        if t > 0:
            if t not in self.pairs:
                self.pairs[t] = []
            self.pairs[t].append((i - 1, i - 1))
            self.open_to_close[i - 1] = i - 1
